//! The film's seventeen-chapter story map, ported from `the-yes-controls.js`.
//!
//! The golden tests below were generated by running the original JavaScript helpers, so
//! moving the map into Rust cannot quietly change which shot the film is on.

use crate::math::{clamp, smooth};

/// The gate leads straight into the opening; the prologue's share of the scroll.
pub const PRO: f64 = 0.004;
/// Half-width of the dip that hides a hard cut, in story progress.
pub const CUT_W: f64 = 0.011;
/// The length, in seconds, of a self-playing film.
/// How long the film takes at 1x: 2:29, with each caption given time to be read.
pub const FILM_SECONDS: f64 = 149.0;

pub const MODE_R: u8 = 0;
pub const MODE_M: u8 = 1;
pub const MODE_N: u8 = 2;
pub const MODE_OLD: u8 = 3;
pub const MODE_C: u8 = 4;
pub const MODE_G: u8 = 5;
pub const MODE_E: u8 = 6;
pub const MODE_F: u8 = 7;
pub const MODE_W: u8 = 8;
pub const MODE_J: u8 = 9;
pub const MODE_H: u8 = 10;
pub const MODE_T: u8 = 11;
pub const MODE_D: u8 = 12;

pub const MODE_NAMES: [&str; 13] = [
    "R", "M", "N", "old", "C", "G", "E", "F", "W", "J", "H", "T", "D",
];

pub fn mode_name(mode: u8) -> &'static str {
    MODE_NAMES.get(usize::from(mode)).copied().unwrap_or("old")
}

pub fn mode_index(name: &str) -> Option<u8> {
    MODE_NAMES
        .iter()
        .position(|candidate| *candidate == name)
        .map(|index| index as u8)
}

#[derive(Clone, Copy, Debug)]
enum Segment {
    Chapter { mode: u8, weight: f64 },
    Old { from: f64, to: f64 },
}

const SEGMENTS: [Segment; 18] = [
    Segment::Chapter {
        mode: MODE_R,
        weight: 0.2,
    },
    Segment::Chapter {
        mode: MODE_M,
        weight: 0.12,
    },
    Segment::Chapter {
        mode: MODE_N,
        weight: 0.68,
    },
    Segment::Old {
        from: 0.1,
        to: 0.285,
    },
    Segment::Chapter {
        mode: MODE_C,
        weight: 0.13,
    },
    Segment::Chapter {
        mode: MODE_G,
        weight: 0.11,
    },
    Segment::Old {
        from: 0.285,
        to: 0.475,
    },
    Segment::Chapter {
        mode: MODE_E,
        weight: 0.24,
    },
    Segment::Old {
        from: 0.475,
        to: 0.62,
    },
    Segment::Chapter {
        mode: MODE_F,
        weight: 0.12,
    },
    Segment::Old {
        from: 0.62,
        to: 0.675,
    },
    Segment::Chapter {
        mode: MODE_W,
        weight: 0.1,
    },
    Segment::Old {
        from: 0.675,
        to: 0.885,
    },
    Segment::Chapter {
        mode: MODE_J,
        weight: 0.11,
    },
    Segment::Chapter {
        mode: MODE_H,
        weight: 0.1,
    },
    Segment::Chapter {
        mode: MODE_T,
        weight: 0.09,
    },
    Segment::Old {
        from: 0.885,
        to: 1.0,
    },
    Segment::Chapter {
        mode: MODE_D,
        weight: 0.19,
    },
];

/// Seconds a cut takes when the film plays itself.
/// The dialogue scenes (the room, the memory, the question) are given the time their captions need
/// to be read; the chapters between them share the rest.
const SEG_SECONDS: [f64; 18] = [
    16.0, 8.5, 44.0, 5.5, 5.0, 5.0, 6.0, 5.0, 4.5, 4.5, 3.5, 5.0, 5.0, 4.5, 5.0, 5.0, 8.0, 9.0,
];

/// Seconds a cut takes at a gentle scroll.
const SCROLL_SECONDS: [f64; 18] = [
    6.0, 5.0, 15.0, 7.0, 5.0, 5.0, 6.0, 7.0, 5.0, 5.0, 3.5, 4.5, 7.0, 6.0, 4.5, 4.5, 6.0, 7.0,
];

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Cut {
    pub a: f64,
    pub b: f64,
    pub mode: u8,
    pub p0: f64,
    pub p1: f64,
    pub t0: f64,
    pub t1: f64,
    pub scroll_sec: f64,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct SceneState {
    pub mode: u8,
    pub p: f64,
    pub local: f64,
    pub fade: f64,
    pub vis: f64,
    pub cut: usize,
}

#[derive(Clone, Debug)]
pub struct StoryMap {
    cuts: Vec<Cut>,
    total_time: f64,
}

impl Default for StoryMap {
    fn default() -> Self {
        Self::new()
    }
}

impl StoryMap {
    pub fn new() -> Self {
        let mut cuts = Vec::with_capacity(SEGMENTS.len());
        let mut acc = 0.0;
        let mut last_p = 0.0;

        for segment in SEGMENTS {
            let (mode, weight, p0, p1) = match segment {
                Segment::Chapter { mode, weight } => (mode, weight, last_p, last_p),
                Segment::Old { from, to } => (MODE_OLD, 0.68 * (to - from), from, to),
            };
            cuts.push(Cut {
                a: acc,
                b: acc + weight,
                mode,
                p0,
                p1,
                t0: 0.0,
                t1: 0.0,
                scroll_sec: 0.0,
            });
            if matches!(segment, Segment::Old { .. }) {
                last_p = p1;
            }
            acc += weight;
        }

        for cut in &mut cuts {
            cut.a /= acc;
            cut.b /= acc;
        }

        let seg_sum: f64 = SEG_SECONDS.iter().sum();
        let mut total_time = 0.0;
        for (index, cut) in cuts.iter_mut().enumerate() {
            cut.t0 = total_time;
            total_time += SEG_SECONDS[index] * FILM_SECONDS / seg_sum;
            cut.t1 = total_time;
            cut.scroll_sec = SCROLL_SECONDS[index];
        }

        Self { cuts, total_time }
    }

    pub fn cuts(&self) -> &[Cut] {
        &self.cuts
    }

    pub fn total_time(&self) -> f64 {
        self.total_time
    }

    /// Which shot is on screen at story progress `s`, and how far into it.
    pub fn map_story(&self, s: f64) -> SceneState {
        let mut cut = self.cuts[self.cuts.len() - 1];
        let mut index = self.cuts.len() - 1;

        for (candidate_index, candidate) in self.cuts.iter().enumerate() {
            if s <= candidate.b {
                cut = *candidate;
                index = candidate_index;
                break;
            }
        }

        let k = if cut.b > cut.a {
            clamp((s - cut.a) / (cut.b - cut.a), 0.0, 1.0)
        } else {
            0.0
        };

        let mut near: f64 = 1.0;
        for candidate in self.cuts.iter().skip(1) {
            near = near.min((s - candidate.a).abs() / CUT_W);
        }
        let dip = if near < 1.0 { 1.0 - smooth(near) } else { 0.0 };

        SceneState {
            mode: cut.mode,
            p: cut.p0 + (cut.p1 - cut.p0) * k,
            local: k,
            fade: 0.0,
            vis: 1.0 - dip,
            cut: index,
        }
    }

    /// Where a guest lands when they pick a chapter of the original eight.
    pub fn s_from_old(&self, p: f64) -> f64 {
        for cut in &self.cuts {
            if cut.mode == MODE_OLD && p <= cut.p1 {
                let span = cut.p1 - cut.p0;
                let k = if span == 0.0 {
                    0.0
                } else {
                    (p - cut.p0) / span
                };
                return cut.a + (cut.b - cut.a) * k.max(0.0);
            }
        }
        self.cuts[self.cuts.len() - 2].b
    }

    /// Where a named chapter starts (or sits at `k` through it).
    pub fn s_from_scene(&self, mode: u8, k: f64) -> f64 {
        for cut in &self.cuts {
            if cut.mode == mode {
                return cut.a + (cut.b - cut.a) * k;
            }
        }
        0.0
    }

    /// Scroll progress includes the prologue, which the story map excludes.
    pub fn raw_from_s(s: f64) -> f64 {
        PRO + s * (1.0 - PRO)
    }

    pub fn t_from_s(&self, s: f64) -> f64 {
        for cut in &self.cuts {
            if s <= cut.b {
                let k = ((s - cut.a) / (cut.b - cut.a)).clamp(0.0, 1.0);
                return cut.t0 + (cut.t1 - cut.t0) * k;
            }
        }
        self.total_time
    }

    pub fn s_from_t(&self, t: f64) -> f64 {
        for cut in &self.cuts {
            if t <= cut.t1 {
                let k = ((t - cut.t0) / (cut.t1 - cut.t0)).clamp(0.0, 1.0);
                return cut.a + (cut.b - cut.a) * k;
            }
        }
        1.0
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn close(actual: f64, expected: f64) {
        assert!(
            (actual - expected).abs() < 1e-12,
            "expected {expected}, got {actual}"
        );
    }

    #[test]
    fn the_story_map_has_eighteen_normalised_cuts() {
        let map = StoryMap::new();
        assert_eq!(map.cuts().len(), SEGMENTS.len());
        close(map.cuts()[0].a, 0.0);
        close(map.cuts()[map.cuts().len() - 1].b, 1.0);
        for pair in map.cuts().windows(2) {
            close(pair[0].b, pair[1].a);
        }
        close(map.total_time(), FILM_SECONDS);
    }

    #[test]
    fn scene_at_matches_the_javascript_map() {
        let map = StoryMap::new();
        let cases = [
            (0.0, "R", 0.0, 0.0, 1.0, 0),
            (0.004, "R", 0.0, 0.056039999999999986, 1.0, 0),
            (0.05, "R", 0.0, 0.7004999999999998, 1.0, 0),
            (
                0.123456,
                "N",
                0.0,
                0.03812310588235276,
                0.932259079146001,
                2,
            ),
            (0.5, "old", 0.33676470588235247, 0.2724458204334342, 1.0, 6),
            (
                0.79,
                "old",
                0.8552647058823526,
                0.858403361344536,
                0.7264409049995358,
                12,
            ),
            (0.999, "D", 1.0, 0.9852526315789474, 1.0, 17),
            (1.0, "D", 1.0, 1.0, 1.0, 17),
        ];

        for (s, mode, p, local, vis, cut) in cases {
            let scene = map.map_story(s);
            assert_eq!(mode_name(scene.mode), mode, "s={s}");
            close(scene.p, p);
            close(scene.local, local);
            close(scene.fade, 0.0);
            close(scene.vis, vis);
            assert_eq!(scene.cut, cut, "s={s}");
        }
    }

    #[test]
    fn chapters_resolve_to_their_cut() {
        let map = StoryMap::new();
        close(map.s_from_scene(MODE_C, 0.0), 0.4017844396859387);
        close(map.s_from_scene(MODE_R, 0.5), 0.035688793718772316);
        close(map.s_from_old(0.5), 0.625267665952891);
        close(map.s_from_scene(255, 0.5), 0.0);
    }

    #[test]
    fn scroll_and_time_round_trip() {
        let map = StoryMap::new();
        close(map.t_from_s(0.0), 0.0);
        close(map.t_from_s(1.0), FILM_SECONDS);
        close(map.s_from_t(0.0), 0.0);
        close(map.s_from_t(FILM_SECONDS), 1.0);
        let mid = 0.42;
        close(map.s_from_t(map.t_from_s(mid)), mid);
    }

    #[test]
    fn raw_progress_includes_the_prologue() {
        close(StoryMap::raw_from_s(0.0), PRO);
        close(StoryMap::raw_from_s(0.5), 0.502);
        close(StoryMap::raw_from_s(1.0), 1.0);
    }

    #[test]
    fn mode_names_round_trip() {
        for (index, name) in MODE_NAMES.iter().enumerate() {
            assert_eq!(mode_name(index as u8), *name);
            assert_eq!(mode_index(name), Some(index as u8));
        }
        assert_eq!(mode_index("nope"), None);
        assert_eq!(mode_name(255), "old");
    }
}
